cat > src/lib/billing-lock.ts <<'EOF'
/**
 * The billing lock: a workspace whose subscription is not in good standing is
 * read-only.
 *
 * `lockReasonFor()` is the pure rule and the only place it is stated. The
 * service layer asks it through `BillingService.assertWorkspaceWritable()`,
 * which throws `WorkspaceLockedError`; `toAppError()` maps that onto the
 * `plan_limit_exceeded` code like every other domain error.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

/** Thrown when a member write reaches a locked (read-only) workspace. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only: ${describeLockReason(reason)}`);
    this.name = "WorkspaceLockedError";
  }
}

function describeLockReason(reason: WorkspaceLockReason): string {
  switch (reason) {
    case "past_due":
      return "its subscription is past due";
    case "canceled":
      return "its subscription has been canceled";
    case "trial_ended":
      return "its trial has ended";
  }
}

/** True once `now` is at or after `stamp`. */
function hasReached(stamp: IsoTimestamp, now: Date): boolean {
  return now.getTime() >= new Date(stamp).getTime();
}

/**
 * Why the workspace owning `subscription` is locked at `now`, or `null` when
 * it is writable.
 *
 * - no subscription row, or an `active` one: writable;
 * - `past_due`: locked;
 * - `trialing`: locked from the moment the period end is reached;
 * - `canceled`: locked from the moment the cancellation date is reached — a
 *   cancellation scheduled for later keeps the workspace writable until then,
 *   and a canceled subscription without a date counts as canceled already.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
    default:
      return null;
  }
}
EOF
