/**
 * Read-only notice shown across the shell while the workspace is locked.
 *
 * Must call (do not reimplement): can
 */
import Link from "next/link";
import { Alert } from "@/components/ui/alert";
import { can } from "@/lib/permissions";
import { settingsPath } from "@/lib/url";
import type { WorkspaceLockReason } from "@/types/billing";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { billingResource } from "../permission/resources";

export type WorkspaceLockBannerProps = {
  lockReason: WorkspaceLockReason | null;
  orgSlug: string;
  actor: Actor;
};

const LOCK_EXPLANATION: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "The last payment for this workspace failed.",
  canceled: "This workspace's subscription has been canceled.",
  trial_ended: "This workspace's trial has ended.",
};

export function WorkspaceLockBanner(
  props: WorkspaceLockBannerProps,
): ReactElement | null {
  const { lockReason, orgSlug, actor } = props;

  if (lockReason === null) return null;

  // Billing stays open while locked; only someone who can use it gets the link.
  const mayFix = can(actor, "org:manage_billing", billingResource(actor.orgId));

  return (
    <Alert tone="warning" title="This workspace is read-only">
      {LOCK_EXPLANATION[lockReason]} Everything can still be viewed, but changes
      are refused until billing is sorted out.
      {mayFix ? (
        <>
          {" "}
          <Link
            href={settingsPath(orgSlug, "billing")}
            className="font-medium underline"
          >
            Choose a plan
          </Link>{" "}
          to unlock it.
        </>
      ) : (
        " Ask an owner to update billing."
      )}
    </Alert>
  );
}
EOF
