    expect(lockReasonFor(trial, AT)).toBe("trial_ended");
    expect(lockReasonFor(trial, AFTER)).toBe("trial_ended");
  });

  it("locks a cancellation from its cancellation date, not before", () => {
    const scheduled = subscription("canceled", {
      cancelAt: PERIOD_END as IsoTimestamp,
    });
    expect(lockReasonFor(scheduled, BEFORE)).toBeNull();
    expect(lockReasonFor(scheduled, AT)).toBe("canceled");
    expect(lockReasonFor(scheduled, AFTER)).toBe("canceled");
  });

  it("counts a canceled subscription with no date as canceled now", () => {
    expect(lockReasonFor(subscription("canceled"), BEFORE)).toBe("canceled");
  });

  it("defaults `now` to the current time", () => {
    const ended = subscription("trialing", {
      currentPeriodEnd: "2000-01-01T00:00:00.000Z" as IsoTimestamp,
    });
    const running = subscription("trialing", {
      currentPeriodEnd: "2999-01-01T00:00:00.000Z" as IsoTimestamp,
    });
    expect(lockReasonFor(ended)).toBe("trial_ended");
    expect(lockReasonFor(running)).toBeNull();
  });
});

describe("lib/billing-lock WorkspaceLockedError", () => {
  it("carries the org, the reason and the plan-limit code", () => {
    const error = new WorkspaceLockedError(ORG_A, "past_due");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("past_due");
  });

  it("maps to `plan_limit_exceeded` with the reason in meta", () => {
    const shape = toAppError(new WorkspaceLockedError(ORG_A, "trial_ended"));
    expect(shape.code).toBe("plan_limit_exceeded");
    expect(shape.meta?.reason).toBe("trial_ended");
    expect(HTTP_STATUS_BY_CODE[shape.code]).toBe(402);
  });

  it("is recognised as a domain error and wrapped as an ActionResult", () => {
    const error = new WorkspaceLockedError(ORG_A, "canceled");
    expect(isDomainError(error)).toBe(true);

    const result = toActionResult(error);
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("plan_limit_exceeded");
    expect(result.error.meta?.reason).toBe("canceled");
  });
});
