/**
 * The billing lock: a workspace whose subscription is not in good standing is
 * read-only. Member writes are refused with `WorkspaceLockedError` straight
 * after their permission check; reads, billing, notification housekeeping and
 * Taskflow's own background work carry on.
 */
import { eq } from "drizzle-orm";
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { WorkspaceLockedError } from "@/lib/billing-lock";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as billingService from "@/server/services/billing-service";
import * as commentService from "@/server/services/comment-service";
import * as featureFlagService from "@/server/services/feature-flag-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SubscriptionStatus, WorkspaceLockReason } from "@/types/billing";
import type { MemberId, OrgId } from "@/types/common";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";

const WRITE_EVENTS: readonly TaskflowEventType[] = [
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "comment.created",
  "comment.deleted",
  "project.created",
  "project.archived",
  "project.restored",
  "member.invited",
  "member.joined",
  "member.role_changed",
  "member.removed",
  "flag.toggled",
];

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Rewrites the stored subscription row — the lock is decided against it. */
function setSubscription(
  orgId: OrgId,
  patch: {
    status: SubscriptionStatus;
    currentPeriodEnd?: string;
    cancelAt?: string | null;
  },
): void {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

/** Counts every write event published until the test ends. */
function watchWriteEvents(): { count: () => number } {
  let seen = 0;
  for (const type of WRITE_EVENTS) {
    detachers.push(
      subscribe(type, () => {
        seen += 1;
      }),
    );
  }
  return { count: () => seen };
}

async function expectLocked(
  attempt: Promise<unknown>,
  orgId: OrgId,
  reason: WorkspaceLockReason,
): Promise<void> {
  const error: unknown = await attempt.then(
    () => null,
    (thrown: unknown) => thrown,
  );
  expect(error).toBeInstanceOf(WorkspaceLockedError);
  expect(error).toMatchObject({
    code: "plan_limit_exceeded",
    orgId,
    reason,
  });
}

async function memberIdOf(tenant: Tenant, role: "admin" | "member" | "viewer"): Promise<MemberId> {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`no ${role} member`);
  return member.id;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("assertWorkspaceWritable", () => {
  it("resolves for a workspace in good standing or without a subscription", async () => {
    const tenant = await createTenant("lock-writable", "growth");
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();

    getDb().delete(subscriptions).where(eq(subscriptions.orgId, tenant.org.id)).run();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
  });

  it("evaluates the stored subscription at the supplied moment", async () => {
    const tenant = await createTenant("lock-moment", "growth");
    setSubscription(tenant.org.id, {
      status: "trialing",
      currentPeriodEnd: "2030-01-10T00:00:00.000Z",
    });

    await expect(
      billingService.assertWorkspaceWritable(
        tenant.org.id,
        new Date("2030-01-09T23:59:59.999Z"),
      ),
    ).resolves.toBeUndefined();

    await expectLocked(
      billingService.assertWorkspaceWritable(
        tenant.org.id,
        new Date("2030-01-10T00:00:00.000Z"),
      ),
      tenant.org.id,
      "trial_ended",
    );
  });

  it("follows the clock: a scheduled cancellation locks once its date arrives", async () => {
    const tenant = await createTenant("lock-clock", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );

    await billingService.cancelSubscription(tenant.actors.owner, {
      orgId: tenant.org.id,
      cancelImmediately: false,
    });
    const scheduled = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(scheduled?.status).toBe("canceled");

    // Still inside the paid-for period: writes go through.
    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Edited before the cancellation date",
      }),
    ).resolves.toMatchObject({ title: "Edited before the cancellation date" });

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date(scheduled?.cancelAt ?? ""));

    await expectLocked(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Edited after the cancellation date",
      }),
      tenant.org.id,
      "canceled",
    );
  });
});

describe("a locked workspace refuses member writes", () => {
  let tenant: Tenant;
  let issue: Issue;

  beforeAll(async () => {
    tenant = await createTenant("lock-writes", "growth");
    issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Before the lock" }),
    );
    setSubscription(tenant.org.id, { status: "past_due" });
  });

  it("refuses every issue write and leaves the issue untouched", async () => {
    const events = watchWriteEvents();
    const { member } = tenant.actors;
    const orgId = tenant.org.id;

    await expectLocked(
      issueService.createIssue(member, issueInput(orgId, tenant.project.id)),
      orgId,
      "past_due",
    );
    await expectLocked(
      issueService.updateIssue(member, { orgId, issueId: issue.id, title: "Nope" }),
      orgId,
      "past_due",
    );
    await expectLocked(
      issueService.changeIssueStatus(member, { orgId, issueId: issue.id, status: "done" }),
      orgId,
      "past_due",
    );
    await expectLocked(
      issueService.moveIssue(member, {
        orgId,
        issueId: issue.id,
        toStatus: "in_progress",
        toIndex: 0,
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      issueService.assignIssue(member, {
        orgId,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      issueService.assignIssue(member, { orgId, issueId: issue.id, assigneeId: null }),
      orgId,
      "past_due",
    );
    await expectLocked(
      issueService.archiveIssue(member, orgId, issue.id),
      orgId,
      "past_due",
    );

    expect(await issueRepo.findIssueById(orgId, issue.id)).toEqual(issue);
    expect(await issueRepo.countIssues(orgId, tenant.project.id)).toBe(1);
    expect(events.count()).toBe(0);
  });

  it("refuses comment writes", async () => {
    const events = watchWriteEvents();
    const orgId = tenant.org.id;
    const comment = await commentRepo.insertComment(
      { orgId, issueId: issue.id, body: "Seeded", parentId: null, mentionedUserIds: [] },
      tenant.userIds.member,
    );

    await expectLocked(
      commentService.createComment(tenant.actors.member, {
        orgId,
        issueId: issue.id,
        body: "Locked out",
        parentId: null,
        mentionedUserIds: [],
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      commentService.updateComment(tenant.actors.member, {
        orgId,
        commentId: comment.id,
        body: "Edited",
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      commentService.deleteComment(tenant.actors.member, { orgId, commentId: comment.id }),
      orgId,
      "past_due",
    );

    expect(await commentRepo.countComments(orgId, issue.id)).toBe(1);
    expect(await commentRepo.findCommentById(orgId, comment.id)).toEqual(comment);
    expect(events.count()).toBe(0);
  });

  it("refuses project, label and attachment writes", async () => {
    const events = watchWriteEvents();
    const orgId = tenant.org.id;
    const { admin, member } = tenant.actors;
    const label = await labelRepo.insertLabel({
      orgId,
      name: "seeded",
      color: "#94a3b8",
      description: null,
    });
    const attachment = await attachmentRepo.insertAttachment(
      { orgId, issueId: issue.id, filename: "a.txt", contentType: "text/plain", sizeBytes: 10 },
      tenant.userIds.member,
    );

    await expectLocked(
      projectService.createProject(member, {
        orgId,
        name: "Locked project",
        slug: "locked-project",
        key: "LOCK",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      projectService.updateProject(admin, {
        orgId,
        projectId: tenant.project.id,
        name: "Renamed",
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      projectService.archiveProject(admin, {
        orgId,
        projectId: tenant.project.id,
        archiveIssues: true,
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      projectService.restoreProject(admin, orgId, tenant.project.id),
      orgId,
      "past_due",
    );

    await expectLocked(
      labelService.createLabel(member, {
        orgId,
        name: "locked",
        color: "#94a3b8",
        description: null,
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      labelService.updateLabel(member, { orgId, labelId: label.id, name: "renamed" }),
      orgId,
      "past_due",
    );
    await expectLocked(
      labelService.deleteLabel(admin, orgId, label.id),
      orgId,
      "past_due",
    );

    await expectLocked(
      attachmentService.addAttachment(member, {
        orgId,
        issueId: issue.id,
        filename: "b.txt",
        contentType: "text/plain",
        sizeBytes: 10,
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      attachmentService.removeAttachment(member, { orgId, attachmentId: attachment.id }),
      orgId,
      "past_due",
    );

    expect(await projectRepo.countProjects(orgId)).toBe(1);
    expect((await projectRepo.findProjectById(orgId, tenant.project.id))?.name).toBe(
      tenant.project.name,
    );
    expect(await labelRepo.listLabels(orgId)).toEqual([label]);
    expect(await attachmentRepo.listAttachments(orgId, issue.id)).toHaveLength(1);
    expect(events.count()).toBe(0);
  });

  it("refuses membership changes and everything about invitations", async () => {
    const events = watchWriteEvents();
    const orgId = tenant.org.id;
    const { admin } = tenant.actors;
    const token = "k".repeat(32);
    const pending = await invitationRepo.insertInvitation(
      orgId,
      { orgId, email: "pending@lock-writes.test", role: "member", expiresInDays: 14 },
      tenant.userIds.admin,
      hashToken(token),
    );
    const invitee = await userRepo.insertUser({
      email: "pending@lock-writes.test",
      name: "Pending",
      passwordHash: "seed",
    });

    await expectLocked(
      memberService.updateMemberRole(admin, {
        orgId,
        memberId: await memberIdOf(tenant, "viewer"),
        role: "member",
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      memberService.removeMember(admin, {
        orgId,
        memberId: await memberIdOf(tenant, "viewer"),
      }),
      orgId,
      "past_due",
    );

    await expectLocked(
      invitationService.inviteMember(admin, {
        orgId,
        email: "new@lock-writes.test",
        role: "member",
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      invitationService.revokeInvitation(admin, pending.id),
      orgId,
      "past_due",
    );
    await expectLocked(
      invitationService.resendInvitation(admin, pending.id),
      orgId,
      "past_due",
    );
    await expectLocked(
      invitationService.acceptInvitation(invitee.id, { token }),
      orgId,
      "past_due",
    );

    // The invitation is still pending and nobody joined or changed role.
    const stillPending = await invitationRepo.listPendingInvitations(orgId);
    expect(stillPending.map((row) => row.id)).toEqual([pending.id]);
    expect(await memberRepo.findMember(orgId, invitee.id)).toBeNull();
    expect(await memberRepo.countActiveMembers(orgId)).toBe(4);
    expect((await memberRepo.findMember(orgId, tenant.userIds.viewer))?.role).toBe("viewer");
    expect(events.count()).toBe(0);
  });

  it("refuses settings, flag overrides and webhook endpoints", async () => {
    const events = watchWriteEvents();
    const orgId = tenant.org.id;
    const { admin } = tenant.actors;
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );

    await expectLocked(
      organizationService.updateOrganization(admin, { orgId, name: "Renamed inc" }),
      orgId,
      "past_due",
    );
    await expectLocked(
      featureFlagService.toggleFlag(admin, { orgId, flag: "csv_export", enabled: true }),
      orgId,
      "past_due",
    );
    await expectLocked(
      webhookService.createWebhook(admin, {
        orgId,
        url: "https://example.test/other",
        eventTypes: ["issue.created"],
      }),
      orgId,
      "past_due",
    );
    await expectLocked(
      webhookService.updateWebhook(admin, { orgId, webhookId: endpoint.id, enabled: false }),
      orgId,
      "past_due",
    );
    await expectLocked(
      webhookService.deleteWebhook(admin, { orgId, webhookId: endpoint.id }),
      orgId,
      "past_due",
    );

    const org = await orgRepo.findOrgById(orgId);
    expect(org?.name).toBe(tenant.org.name);
    expect(org?.settings.enabledFlagOverrides).toEqual([]);
    expect(await webhookRepo.listEndpoints(orgId)).toEqual([endpoint]);
    expect(events.count()).toBe(0);
  });

  it("still gives a caller who would have been refused anyway the same refusal", async () => {
    const orgId = tenant.org.id;
    const outsider = await createTenant("lock-outsider", "growth");

    await expect(
      issueService.createIssue(tenant.actors.viewer, issueInput(orgId, tenant.project.id)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      issueService.updateIssue(outsider.actors.owner, {
        orgId,
        issueId: issue.id,
        title: "Cross-tenant",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      invitationService.inviteMember(tenant.actors.member, {
        orgId,
        email: "x@lock-writes.test",
        role: "member",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      featureFlagService.toggleFlag(outsider.actors.owner, {
        orgId,
        flag: "csv_export",
        enabled: true,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      invitationService.acceptInvitation(tenant.userIds.viewer, { token: "z".repeat(32) }),
    ).rejects.toThrow(/was not found/);

    const revokedToken = "r".repeat(32);
    const revoked = await invitationRepo.insertInvitation(
      orgId,
      { orgId, email: "revoked@lock-writes.test", role: "member", expiresInDays: 14 },
      tenant.userIds.admin,
      hashToken(revokedToken),
    );
    await invitationRepo.revokeInvitation(orgId, revoked.id);
    await expect(
      invitationService.acceptInvitation(tenant.userIds.viewer, { token: revokedToken }),
    ).rejects.toThrow(/revoked/);
  });
});

describe("a locked workspace keeps working where it must", () => {
  it("serves reads and reports the lock on both summaries", async () => {
    const tenant = await createTenant("lock-reads", "growth");
    const orgId = tenant.org.id;
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId, tenant.project.id),
    );

    const open = await organizationService.getOrganizationSummary(tenant.actors.viewer, orgId);
    expect(open.lockReason).toBeNull();
    expect(
      (await billingService.getBillingSummary(tenant.actors.owner, orgId)).lockReason,
    ).toBeNull();

    setSubscription(orgId, { status: "canceled", cancelAt: null });

    expect((await issueService.getIssue(tenant.actors.viewer, orgId, issue.id)).issue.id).toBe(
      issue.id,
    );
    expect(
      (await issueService.listIssues(tenant.actors.viewer, { orgId, limit: 10, cursor: null }))
        .items,
    ).toHaveLength(1);
    expect(await commentService.getThread(tenant.actors.viewer, orgId, issue.id)).toEqual([]);
    expect(
      (await projectService.listProjects(tenant.actors.viewer, { orgId, limit: 10, cursor: null }))
        .items,
    ).toHaveLength(1);

    const locked = await organizationService.getOrganizationSummary(tenant.actors.viewer, orgId);
    expect(locked.lockReason).toBe("canceled");
    expect(
      (await billingService.getBillingSummary(tenant.actors.owner, orgId)).lockReason,
    ).toBe("canceled");
  });

  it("keeps billing open, and a plan change unlocks the workspace", async () => {
    const tenant = await createTenant("lock-billing", "growth");
    const orgId = tenant.org.id;
    const { owner, member } = tenant.actors;

    await billingService.cancelSubscription(owner, { orgId, cancelImmediately: true });
    await expectLocked(
      issueService.createIssue(member, issueInput(orgId, tenant.project.id)),
      orgId,
      "canceled",
    );

    await expect(billingService.updateSeats(owner, { orgId, seats: 6 })).resolves.toMatchObject({
      seats: 6,
    });
    await expectLocked(
      issueService.createIssue(member, issueInput(orgId, tenant.project.id)),
      orgId,
      "canceled",
    );

    await billingService.changePlan(owner, { orgId, plan: "starter", interval: "monthly" });

    expect((await billingService.getBillingSummary(owner, orgId)).lockReason).toBeNull();
    await expect(
      issueService.createIssue(member, issueInput(orgId, tenant.project.id)),
    ).resolves.toMatchObject({ orgId });
  });

  it("still lets the workspace be deleted", async () => {
    const tenant = await createTenant("lock-delete", "growth");
    setSubscription(tenant.org.id, { status: "past_due" });

    const archived = await organizationService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(archived.archivedAt).not.toBeNull();
  });

  it("still lets a member tidy their own notifications", async () => {
    const tenant = await createTenant("lock-notifications", "growth");
    const orgId = tenant.org.id;
    setSubscription(orgId, { status: "past_due" });

    // The fan-out is Taskflow's own work, so it still writes rows.
    const [notification] = await notificationService.notify(
      orgId,
      "issue_assigned",
      [tenant.userIds.member],
      { title: "Assigned", body: "Yours now", href: "/issues/1", actorId: null },
    );
    expect(notification).toBeDefined();
    if (!notification) return;

    const read = await notificationService.markRead(tenant.actors.member, {
      orgId,
      notificationId: notification.id,
    });
    expect(read.readAt).not.toBeNull();
    await expect(notificationService.markAllRead(tenant.actors.member, orgId)).resolves.toBe(0);
    await expect(
      notificationService.updatePreference(tenant.actors.member, {
        orgId,
        userId: tenant.userIds.member,
        kind: "issue_assigned",
        inApp: true,
        email: false,
        digestOnly: false,
      }),
    ).resolves.toMatchObject({ email: false });

    const stored = await notificationRepo.listNotifications({
      orgId,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 10,
      cursor: null,
    });
    expect(stored.items).toHaveLength(1);
  });

  it("lets the trial-expiry job unlock an ended trial that fits the free plan", async () => {
    const fits = await createTenant("lock-trial-fits", "growth");
    const outgrown = await createTenant("lock-trial-outgrown", "growth");
    const ended = "2026-02-01T00:00:00.000Z";
    const now = new Date("2026-02-02T00:00:00.000Z");

    for (const tenant of [fits, outgrown]) {
      setSubscription(tenant.org.id, { status: "trialing", currentPeriodEnd: ended });
    }
    // Four seats are more than the free plan's three; one seat fits.
    await usageRepo.recomputeUsage(outgrown.org.id);
    await usageRepo.incrementUsage(fits.org.id, { seatsUsed: 1, projectsUsed: 1 });

    for (const tenant of [fits, outgrown]) {
      await expectLocked(
        billingService.assertWorkspaceWritable(tenant.org.id, now),
        tenant.org.id,
        "trial_ended",
      );
    }

    await runTrialExpiryJob(now);

    expect((await subscriptionRepo.findSubscription(fits.org.id))?.plan).toBe("free");
    await expect(
      billingService.assertWorkspaceWritable(fits.org.id, now),
    ).resolves.toBeUndefined();

    // Too big for the free plan: left alone, and locked until a plan is chosen.
    await expectLocked(
      billingService.assertWorkspaceWritable(outgrown.org.id, now),
      outgrown.org.id,
      "trial_ended",
    );
    await billingService.changePlan(outgrown.actors.owner, {
      orgId: outgrown.org.id,
      plan: "growth",
      interval: "monthly",
    });
    await expect(
      billingService.assertWorkspaceWritable(outgrown.org.id, now),
    ).resolves.toBeUndefined();
  });
});

